  let iterations = 0;
  for (;;) {
    if (++iterations > 4096) return null;
    if (cursor === queue.length) {
      const result = {};
      for (const [name, version] of selected) {
        Object.defineProperty(result, name, { value: version.text, enumerable: true, writable: true, configurable: true });
      }
      return result;
    }
