'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Backtracking must undo constraints from abandoned choices.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
}, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// Abandoned choice's deps must not leak (x only reachable through a@2).
assert.deepEqual(resolve({
  a: { '2.0.0': { x: '*', z: '1.0.0' }, '1.0.0': {} },
  x: { '1.0.0': {} },
  z: { '2.0.0': {} },
}, { a: '*' }), { a: '1.0.0' });

// Cycles.
assert.deepEqual(resolve({
  a: { '1.0.0': { b: '^1.0.0' } },
  b: { '1.0.0': { a: '^1.0.0', b: '1.0.0' } },
}, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
assert.equal(resolve({ a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '2.0.0' } } }, { a: '*' }), null);

// Long chain.
const N = 200000;
const reg = {};
for (let i = 0; i < N; i += 1) reg[`p${i}`] = { '1.0.0': i + 1 < N ? { [`p${i + 1}`]: '*' } : { p0: '1.0.0' } };
assert.equal(Object.keys(resolve(reg, { p0: '*' })).length, N);

// No Cartesian product before checking discovered constraints.
const wide = { miss: undefined };
delete wide.miss;
const rootWide = {};
for (let i = 0; i < 40; i += 1) { wide[`q${i}`] = { '1.0.0': {}, '2.0.0': {} }; rootWide[`q${i}`] = '*'; }
rootWide.missing = '*';
let t = Date.now();
assert.equal(resolve(wide, rootWide), null);
const wide2 = { ...wide, r: { '1.0.0': {} } };
const root2 = { ...rootWide }; delete root2.missing; root2.r = '1.0.0'; root2.r2 = 'x';
assert.throws(() => resolve(wide2, root2), TypeError);
delete root2.r2;
const wide3 = { ...wide2, last: { '1.0.0': { r: '2.0.0' } } };
assert.equal(resolve(wide3, { ...root2, last: '*' }), null);
assert.ok(Date.now() - t < 1000);

// Caret on zero majors.
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '^1.2.0'), true);
assert.equal(satisfies('2.0.0', '^1.2.0'), false);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// Validation and edge cases.
assert.throws(() => resolve({ a: { '01.0.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ a: { '1.0.0': { b: '' } } }, {}), TypeError);
assert.throws(() => resolve({ a: [] }, {}), TypeError);
assert.deepEqual(resolve({}, {}), {});
assert.equal(resolve({}, { nope: '*' }), null);
const frozen = Object.freeze({ a: Object.freeze({ '1.0.0': Object.freeze({}) }) });
assert.deepEqual(resolve(frozen, Object.freeze({ a: '*' })), { a: '1.0.0' });
console.log('smoke ok');

